. (Join-Path $PSScriptRoot 'cloud-common.ps1')
foreach($name in 'cml-vehicles','cml-fuel','cml-reminders'){try{Invoke-Aws logs create-log-group --log-group-name "/aws/lambda/$name"|Out-Null}catch{}}
Invoke-Aws cloudwatch put-metric-alarm --alarm-name motorlog-api-errors --namespace Motorlog/Application --metric-name API5xxErrors --dimensions 'Name=Environment,Value=floci' --statistic Sum --period 60 --evaluation-periods 1 --threshold 1 --comparison-operator GreaterThanOrEqualToThreshold --treat-missing-data notBreaching|Out-Null
Invoke-Aws cloudwatch put-metric-alarm --alarm-name motorlog-reminder-failures --namespace Motorlog/Application --metric-name NotificationFailures --dimensions 'Name=Environment,Value=floci' 'Name=Service,Value=reminders' 'Name=Operation,Value=notification' --statistic Sum --period 300 --evaluation-periods 2 --datapoints-to-alarm 2 --threshold 1 --comparison-operator GreaterThanOrEqualToThreshold --treat-missing-data notBreaching|Out-Null
Invoke-Aws cloudwatch put-metric-alarm --alarm-name motorlog-notification-dlq --namespace AWS/SQS --metric-name ApproximateNumberOfMessagesVisible --dimensions 'Name=QueueName,Value=cml-reminder-notifications-dlq' --statistic Maximum --period 60 --evaluation-periods 1 --threshold 1 --comparison-operator GreaterThanOrEqualToThreshold --treat-missing-data notBreaching|Out-Null
Write-Host 'CloudWatch log groups and alarms deployed. No schedule, queue, or email settings were changed.'
